/**
 * BRSR Social & Governance indicator catalog (Principles 1–5, 7–9) with XBRL hints.
 */
const BRSR_SG_INDICATOR_CATALOG = Object.freeze([
  { id: 'board_oversight', principle: 1, label: 'Board oversight of sustainability', multiline: true, xbrlPath: 'governance.boardApprovedPolicy' },
  { id: 'anti_corruption_policy', principle: 1, label: 'Anti-corruption / ethics policy', multiline: true, required: false },
  { id: 'conflict_of_interest', principle: 1, label: 'Conflict of interest disclosure', multiline: true },
  { id: 'product_safety', principle: 2, label: 'Product safety practices', multiline: true },
  { id: 'sustainable_innovation', principle: 2, label: 'Sustainable innovation initiatives', multiline: true },
  { id: 'customer_feedback', principle: 2, label: 'Customer feedback mechanism', multiline: true },
  { id: 'workforce_count', principle: 3, label: 'Workforce count', placeholder: 'e.g. 120', required: true, xbrlPath: 'workforce.total' },
  { id: 'gender_diversity', principle: 3, label: 'Gender diversity disclosure', placeholder: 'e.g. 32% women', required: true, xbrlPath: 'workforce.permanentFemale' },
  { id: 'health_safety', principle: 3, label: 'Occupational health & safety', multiline: true },
  { id: 'training_hours', principle: 3, label: 'Employee training hours', placeholder: 'e.g. 24 hours/employee/year' },
  { id: 'stakeholder_mapping', principle: 4, label: 'Stakeholder mapping', multiline: true },
  { id: 'grievance_mechanism', principle: 4, label: 'Grievance mechanism', multiline: true, required: true },
  { id: 'community_engagement', principle: 4, label: 'Community engagement', multiline: true },
  { id: 'human_rights_policy', principle: 5, label: 'Human rights policy', multiline: true, required: true },
  { id: 'child_forced_labour', principle: 5, label: 'Child / forced labour policy', multiline: true },
  { id: 'supplier_code_of_conduct', principle: 5, label: 'Supplier code of conduct', multiline: true },
  { id: 'policy_advocacy_disclosure', principle: 7, label: 'Policy advocacy disclosure', multiline: true },
  { id: 'trade_association_membership', principle: 7, label: 'Trade association membership', multiline: true },
  { id: 'sme_supplier_development', principle: 8, label: 'SME / supplier development', multiline: true },
  { id: 'community_investment', principle: 8, label: 'Community investment programs', multiline: true },
  { id: 'csr_spend', principle: 8, label: 'CSR spend (INR)', placeholder: 'e.g. 250000' },
  { id: 'consumer_complaints', principle: 9, label: 'Consumer complaints process', multiline: true },
  { id: 'data_privacy', principle: 9, label: 'Customer data privacy practices', multiline: true },
  { id: 'product_labelling', principle: 9, label: 'Product labelling & information', multiline: true }
]);

const BRSR_SG_PRINCIPLE_TITLES = Object.freeze({
  1: 'Ethics, transparency and accountability',
  2: 'Products/services for sustainable value',
  3: 'Employee well-being',
  4: 'Stakeholder engagement',
  5: 'Human rights',
  7: 'Public and regulatory policy advocacy',
  8: 'Inclusive growth and equitable development',
  9: 'Customer value'
});

const BRSR_SG_PRINCIPLES = Object.freeze(
  [1, 2, 3, 4, 5, 7, 8, 9].map((principle) => ({
    principle,
    title: BRSR_SG_PRINCIPLE_TITLES[principle],
    indicators: BRSR_SG_INDICATOR_CATALOG.filter((row) => row.principle === principle).map((row) => row.id)
  }))
);

const mapSgCaptureToXbrlOverlay = (hubRecord = {}, msmeData = {}) => {
  const sg = hubRecord?.exportProfile?.brsrSocialGovernance || {};
  const parseNumeric = (value) => {
    const match = String(value || '').replace(/,/g, '').match(/-?\d+(?:\.\d+)?/);
    return match ? Number(match[0]) : null;
  };
  const principles = {};
  BRSR_SG_PRINCIPLES.forEach(({ principle, indicators }) => {
    const disclosedCount = indicators.filter((id) => {
      const row = sg[id];
      return row?.disclosed && (row.value || row.note);
    }).length;
    principles[`p${principle}`] = { reported: disclosedCount >= Math.min(2, indicators.length) };
  });

  const workforceTotal = Number(
    sg.workforce_count?.value
    || msmeData?.business?.employeeCount
    || msmeData?.business?.numberOfEmployees
    || 0
  );
  const genderText = String(sg.gender_diversity?.value || '');
  const femalePctMatch = genderText.match(/(\d+(?:\.\d+)?)\s*%/);
  const femalePct = femalePctMatch ? Number(femalePctMatch[1]) : null;
  const permanentFemale = femalePct != null && workforceTotal > 0
    ? Math.round(workforceTotal * (femalePct / 100))
    : null;

  const narrativeParts = BRSR_SG_INDICATOR_CATALOG
    .filter((row) => row.multiline && sg[row.id]?.disclosed && (sg[row.id]?.value || sg[row.id]?.note))
    .map((row) => `${row.label}: ${String(sg[row.id].value || sg[row.id].note).trim()}`)
    .slice(0, 8);

  return {
    principles,
    workforce: {
      total: workforceTotal > 0 ? workforceTotal : null,
      permanentFemale,
      permanentMale: workforceTotal > 0 && permanentFemale != null
        ? Math.max(workforceTotal - permanentFemale, 0)
        : null,
      femalePercent: femalePct,
      trainingHoursPerEmployee: parseNumeric(sg.training_hours?.value)
    },
    governance: {
      policyCoversAllPrinciples: principles.p1?.reported && principles.p2?.reported,
      boardApprovedPolicy: Boolean(sg.board_oversight?.disclosed && sg.board_oversight?.value),
      proceduresInPlace: Boolean(sg.grievance_mechanism?.disclosed && sg.grievance_mechanism?.value),
      implementationMechanism: Boolean(sg.stakeholder_mapping?.disclosed),
      performanceReview: narrativeParts.length > 0
        ? narrativeParts.join(' | ')
        : (sg.community_engagement?.value || sg.grievance_mechanism?.value || null),
      csrSpendInr: parseNumeric(sg.csr_spend?.value),
      grievanceMechanism: Boolean(sg.grievance_mechanism?.disclosed && sg.grievance_mechanism?.value)
    },
    sgNarrativeFacts: narrativeParts,
    indicatorCount: Object.values(sg).filter((row) => row?.disclosed && (row.value || row.note)).length
  };
};

export {
  BRSR_SG_INDICATOR_CATALOG,
  BRSR_SG_PRINCIPLES,
  BRSR_SG_PRINCIPLE_TITLES,
  mapSgCaptureToXbrlOverlay
};
